(* [comment removed for export] *)
Definition dof_exitA_stmt (pc e loc : Z) : Prop :=
  forall rax ra sp gp tp t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s1x s2x s3x s4x s5 s6 s7
         s0v s1v s2v s3v s4v s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m m1 : mem) (P E lo : Z) (c c1 : pcore) (pad7 pad2 : list byte) (vp : Z) (vbs : list byte)
    (j1 junk j2 : list byte) (e1 e2 e3 : word) (g : bool),
  dof_ctx m m1 sp (dof_sv s4v s3v s2v s1v s0v ra) P E lo c1 pad7 pad2 vp vbs e1 e2 e3 g ->
  rw_cells usegs m1 (bv_unsigned sp + -288) [CB 200 j1] ->
  rw_cells usegs m1 (bv_unsigned sp + -88) [CB 24 junk] ->
  rw_cells usegs m1 (bv_unsigned sp + -64) [CB 16 j2] ->
  dof_pure sp P E lo c (pc_state c) vp vbs -> dof_core c c1 ->
  In e [HE_BAD_VALUE; HE_BAD_CONTENT_LENGTH; HE_BAD_TRANSFER_ENCODING; HE_MULTIPLE_CONTENT_LENGTH] ->
  evt usegs (dof_post ra sp gp tp s0v s1v s2v s3v s4v s5 s6 s7 s8 s9 s10 s11 F fc P E lo c pad7 pad2 vp vbs m)
    (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -288)) gp tp t0 t1 t2 (wz E) s1x a0 a1 a2 a3 a4 a5 a6 a7
              s2x s3x s4x s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 pc) fc None m1 (seg_rom usegs)).

Local Ltac dof_exit_script e loc TOFF pcstop :=
  intros rax ra sp gp tp t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s1x s2x s3x s4x s5 s6 s7 s0v s1v s2v s3v s4v s8 s9 s10 s11 t3 t4 t5 t6
         F fc m m1 P E lo c c1 pad7 pad2 vp vbs j1 junk j2 e1 e2 e3 g;
  intros CTX FR1 TMP FR2 PURE DC HE;
  pose proof PURE as PURE0;
  destruct CTX as (FRhi & PC & EC & WIN & HC & XS & ST & MU & WM & MI);
  destruct PURE as (PCOK & FLD & LO & IMG & QLO & QHI & PLO & PHI & ELO & EHI & DPE & VLEN);
  pose proof (bytes_at_bound _ _ _ _ WIN) as WB;
  pose proof (bv_unsigned_in_range 64 sp) as SPR; unfold bv_modulus in SPR; change (2 ^ Z.of_N 64) with (2^64) in SPR;
  unfold dof_W, G_HTTP_CAT in *; unfold dof_sv in FRhi; cbn [map] in FRhi;
  unfold ParserCoreCells in PC; cbn [pc_blim_has pc_blim pc_len pc_len0 pc_skip pc_hlim pc_state pc_f] in PC;
  unfold wz in *;
  (* [comment removed for export] *)
  steps_to 0x34360%Z;
  call_assignA_with (bv_unsigned sp + -288) (bv_unsigned sp + TOFF) e lo g junk;
  clear HC XS;
  lazymatch goal with
  | TMP' : rw_cells _ ?mx (bv_unsigned sp + TOFF) (ErrCodeCells _), HC : HttpCat _ true, XS : XStatics _, ST' : stk _ _ lo _ |- _ =>
    concretize_ec TMP';
    steps_to pcstop;
    (* [comment removed for export] *)
    destruct (rw_cells_forget _ _ _ _ TMP') as [junk' TMPb]; cbn [cells_size csize Nat.add] in TMPb; clear TMP';
    pose proof (rw_cells_CB_join usegs _ _ _ _ _ _ FR1 ltac:(lazymatch type of TMPb with rw_cells _ _ ?a _ =>
        replace a with (bv_unsigned sp + -288 + Z.of_nat 200) in TMPb by lia end; exact TMPb)) as J1;
    clear FR1 TMPb;
    pose proof (rw_cells_CB_join usegs _ _ _ _ _ _ J1 ltac:(lazymatch type of FR2 with rw_cells _ _ ?a _ =>
        replace a with (bv_unsigned sp + -288 + Z.of_nat (200 + 24)) in FR2 by lia end; exact FR2)) as J2;
    clear J1 FR2; change (200 + 24 + 16)%nat with 240%nat in J2;
    let T := fresh "TL" in pose proof dof_tail as T; unfold dof_tail_stmt in T; unfold wz, G_HTTP_CAT in T;
    eapply (T _ ra sp _ _ _ _ _ _ _ _ _ _ _ _ _ _ s5 s6 s7 s0v s1v s2v s3v s4v _ _ _ _ _ _ _ _ F fc m mx P E lo c c1 pad7 pad2 vp vbs e loc _ e1 e2 e3);
    [ unfold dof_ctx, dof_sv, dof_W, G_HTTP_CAT, ParserCoreCells; cbn [map pc_blim_has pc_blim pc_len pc_len0 pc_skip pc_hlim pc_state pc_f]; unfold wz;
      repeat match goal with |- _ /\ _ => split end; eassumption
    | exact J2 | exact PURE0 | exact DC | exact HE | reflexivity | lia | lia ]
  end.
Scheme kc__2 := Elimination for Corelib.Init.Logic.ex Sort Prop.

