(* [comment removed for export] *)
Definition dof_lambda_stmt : Prop :=
  forall rax ra sp gp tp t0 t1 t2 a0x a1 a2 a3 a4 a5 a6 a7 s1x s2x s3x s4x s5 s6 s7
         s0v s1v s2v s3v s4v s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m m1 : mem) (P E lo : Z) (c c1 : pcore) (pad7 pad2 : list byte) (vp : Z) (vbs : list byte)
    (j1 j2 : list byte) (e1 e2 e3 : word) (g : bool),
  dof_ctx m m1 sp (dof_sv s4v s3v s2v s1v s0v ra) P E lo c1 pad7 pad2 vp vbs e1 e2 e3 g ->
  rw_cells usegs m1 (bv_unsigned sp + -288) [CB 192 j1] ->
  rw_cells usegs m1 (bv_unsigned sp + -96) [C8 (wz E)] ->
  rw_cells usegs m1 (bv_unsigned sp + -88) [CB 40 j2] ->
  dof_pure sp P E lo c (pc_state c) vp vbs -> dof_core c c1 ->
  E mod 8 = 0 ->                                                              (* [comment removed for export] *)
  evt usegs (dof_post ra sp gp tp s0v s1v s2v s3v s4v s5 s6 s7 s8 s9 s10 s11 F fc P E lo c pad7 pad2 vp vbs m)
    (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -288)) gp tp t0 t1 t2 (wz E) s1x a0x a1 a2 a3 a4 a5 a6 a7
              s2x s3x s4x s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 0x3f778) fc None m1 (seg_rom usegs)).
